syntax:
template <intmax_t N, intmax_t D = 1> class ratio;
// Represents a rational number N/D at compile time
// Arithmetic operations are provided via template specializations and metafunctions

code_example:
#include <ratio>
#include <iostream>

using namespace std;

// Define some ratios
using Half = ratio<1, 2>;
using Third = ratio<1, 3>;

// Compile-time addition of ratios
using Sum = ratio_add<Half, Third>::type;

int main() {
    // Output the numerator and denominator of the sum
    cout << "Sum numerator: " << Sum::num << endl;
    cout << "Sum denominator: " << Sum::den << endl;
    return 0;
}
